type UserOptions = BTreeMap<String, String>;

/// What format expansion reads without holding the engine: `#{pane_kind}` and
/// `#{@name}` readback, keyed by the ids a `StatusContext` already carries.
#[derive(Clone, Debug, Default)]
pub struct FormatFacts {
    pane_kinds: BTreeMap<String, &'static str>,
    pane_windows: BTreeMap<String, String>,
    server: UserOptions,
    global_session: UserOptions,
    sessions: BTreeMap<String, UserOptions>,
    global_window: UserOptions,
    windows: BTreeMap<String, UserOptions>,
    panes: BTreeMap<String, UserOptions>,
}

impl FormatFacts {
    #[must_use]
    pub fn pane_kind(&self, pane: &str) -> Option<&'static str> {
        self.pane_kinds.get(pane).copied()
    }

    /// A user option as `#{@name}` sees it: pane, then the pane's window,
    /// session, global window, global session, server.
    #[must_use]
    pub fn user_option(&self, pane: &str, window: &str, session: &str, name: &str) -> Option<&str> {
        let window = self.pane_windows.get(pane).map_or(window, String::as_str);
        self.panes
            .get(pane)
            .and_then(|values| values.get(name))
            .or_else(|| self.windows.get(window).and_then(|values| values.get(name)))
            .or_else(|| {
                self.sessions
                    .get(session)
                    .and_then(|values| values.get(name))
            })
            .or_else(|| self.global_window.get(name))
            .or_else(|| self.global_session.get(name))
            .or_else(|| self.server.get(name))
            .map(String::as_str)
    }
}

fn pane_kind_name(kind: &PaneKind) -> &'static str {
    match kind {
        PaneKind::Picker { .. } => "picker",
        PaneKind::Terminal => "terminal",
        PaneKind::Browser(_) => "browser",
        PaneKind::Agent(_) => "agent",
        PaneKind::Editor(_) => "editor",
    }
}

#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
enum ArrayIndex {
    Numeric(u32),
    Named(String),
}

impl ArrayIndex {
    fn parse(value: String) -> Self {
        value
            .parse()
            .map_or_else(|_| Self::Named(value), Self::Numeric)
    }

    fn display(&self) -> String {
        match self {
            Self::Numeric(index) => index.to_string(),
            Self::Named(index) => index.clone(),
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
enum FormatOptionIndex {
    Whole,
    Indexed(ArrayIndex),
    Invalid,
}

fn parse_format_option(input: &str) -> Option<(TmuxOption, FormatOptionIndex)> {
    let (name, index) = if let Some(open) = input.find('[') {
        let name = &input[..open];
        let rest = &input[open + 1..];
        let index = rest
            .strip_suffix(']')
            .filter(|value| !value.is_empty() && !value.contains('[') && !value.contains(']'))
            .and_then(|value| {
                if value.bytes().all(|byte| byte.is_ascii_digit()) {
                    value.parse::<u32>().ok().map(ArrayIndex::Numeric)
                } else {
                    Some(ArrayIndex::Named(value.to_owned()))
                }
            })
            .map_or(FormatOptionIndex::Invalid, FormatOptionIndex::Indexed);
        (name, index)
    } else {
        (input, FormatOptionIndex::Whole)
    };
    let option = exact_tmux_option(name)?;
    if !TMUX_OPTION_CONSUMERS.contains(&option.name) {
        return None;
    }
    if matches!(
        option.name,
        "command-alias" | "status-format" | "update-environment"
    ) {
        return Some((option, index));
    }
    matches!(index, FormatOptionIndex::Whole).then_some((option, index))
}

fn format_option_map_value(
    values: &BTreeMap<String, String>,
    name: &str,
    index: &FormatOptionIndex,
) -> Option<String> {
    match index {
        FormatOptionIndex::Whole => values.get(name).cloned(),
        FormatOptionIndex::Indexed(index) => Some(
            values
                .get(&format!("{name}[{}]", index.display()))
                .cloned()
                .unwrap_or_default(),
        ),
        FormatOptionIndex::Invalid => Some(String::new()),
    }
}

fn parse_session_id(value: &str) -> Option<SessionId> {
    value.strip_prefix('$')?.parse().ok().map(SessionId)
}

fn parse_window_id(value: &str) -> Option<WindowId> {
    value.strip_prefix('@')?.parse().ok().map(WindowId)
}

fn parse_pane_id(value: &str) -> Option<PaneId> {
    value.strip_prefix('%')?.parse().ok().map(PaneId)
}

