    #[test]
    fn detached_new_session_uses_default_size_with_per_dimension_overrides() {
        let mut engine = MuxEngine::default();
        let mut context = ExecutionContext::default();
        engine
            .execute(
                &mut context,
                &command("set-option", &["-g", "default-size", "132x43"]),
            )
            .unwrap();
        engine
            .execute(&mut context, &command("new-session", &["-d", "-s", "wide"]))
            .unwrap();
        assert_eq!(
            engine.state.windows[&context.window.unwrap()]
                .layout
                .extent(),
            (132, 43)
        );
        engine
            .execute(
                &mut context,
                &command("new-session", &["-d", "-s", "tall", "-x", "90"]),
            )
            .unwrap();
        assert_eq!(
            engine.state.windows[&context.window.unwrap()]
                .layout
                .extent(),
            (90, 43)
        );
        engine
            .execute(
                &mut context,
                &command("new-session", &["-d", "-s", "dash-width", "-x", "-"]),
            )
            .unwrap();
        assert_eq!(
            engine.state.windows[&context.window.unwrap()]
                .layout
                .extent(),
            (80, 43)
        );
        engine
            .execute(
                &mut context,
                &command("new-session", &["-d", "-s", "dash-height", "-y", "-"]),
            )
            .unwrap();
        assert_eq!(
            engine.state.windows[&context.window.unwrap()]
                .layout
                .extent(),
            (132, 24)
        );
        engine
            .execute(
                &mut context,
                &command(
                    "new-session",
                    &["-d", "-s", "dash-both", "-x", "-", "-y", "-"],
                ),
            )
            .unwrap();
        assert_eq!(
            engine.state.windows[&context.window.unwrap()]
                .layout
                .extent(),
            (80, 24)
        );
        engine
            .execute(
                &mut context,
                &command("set-option", &["-g", "default-size", "0x20000tail"]),
            )
            .unwrap();
        engine
            .execute(
                &mut context,
                &command("new-session", &["-d", "-s", "clamped"]),
            )
            .unwrap();
        assert_eq!(
            engine.state.windows[&context.window.unwrap()]
                .layout
                .extent(),
            (1, 10_000)
        );
    }

