    #[test]
    fn word_separators_are_live_inherited_session_options() {
        let mut engine = MuxEngine::default();
        let mut context = ExecutionContext::default();
        engine
            .execute(&mut context, &command("new-session", &["-s", "first"]))
            .expect("first session");
        let first_session = context.session.expect("first session id");
        let first_pane = context.pane.expect("first pane");
        assert_eq!(
            engine.word_separators_for_pane(first_pane).unwrap(),
            DEFAULT_WORD_SEPARATORS
        );

        let global = engine
            .execute(
                &mut context,
                &command("set-option", &["-g", "word-separators", ""]),
            )
            .expect("empty global separators");
        assert_eq!(
            global.effects,
            [
                MuxEffect::WordSeparatorsChanged { session: None },
                MuxEffect::MuxOptionChanged {
                    option: MuxOptionKey::WordSeparators,
                    session: None,
                },
            ]
        );
        assert_eq!(engine.word_separators_for_session(first_session), "");

        let targeted = engine
            .execute(
                &mut context,
                &command(
                    "set-option",
                    &["-t", &first_session.to_string(), "word-separators", "."],
                ),
            )
            .expect("session separators");
        assert_eq!(
            targeted.effects,
            [MuxEffect::WordSeparatorsChanged {
                session: Some(first_session)
            }]
        );
        engine
            .execute(
                &mut context,
                &command(
                    "set-option",
                    &[
                        "-a",
                        "-t",
                        &first_session.to_string(),
                        "word-separators",
                        "λ",
                    ],
                ),
            )
            .expect("append unicode separator");
        assert_eq!(engine.word_separators_for_session(first_session), ".λ");

        engine
            .execute(
                &mut context,
                &command("set-option", &["-g", "word-separators", "|"]),
            )
            .expect("replace global separators");
        assert_eq!(engine.word_separators_for_session(first_session), ".λ");
        engine
            .execute(
                &mut context,
                &command(
                    "set-option",
                    &["-u", "-t", &first_session.to_string(), "word-separators"],
                ),
            )
            .expect("restore inheritance");
        assert_eq!(engine.word_separators_for_session(first_session), "|");

        let oversized = "x".repeat(MAX_WORD_SEPARATORS_BYTES + 1);
        assert!(
            engine
                .execute(
                    &mut context,
                    &command("set-option", &["-g", "word-separators", &oversized]),
                )
                .is_err()
        );
        assert_eq!(engine.word_separators_for_session(first_session), "|");
    }

    #[test]
    fn mode_keys_follow_window_scope_inheritance_and_live_effects() {
        let mut engine = MuxEngine::default();
        let mut context = ExecutionContext::default();
        engine
            .execute(&mut context, &command("new-session", &["-s", "modes"]))
            .expect("first window");
        let first_window = context.window.expect("first window id");
        let first_pane = context.pane.expect("first pane");
        engine
            .execute(&mut context, &command("new-window", &["-n", "second"]))
            .expect("second window");
        let second_window = context.window.expect("second window id");
        let second_pane = context.pane.expect("second pane");
        assert_eq!(
            engine.copy_mode_table_for_pane(first_pane).unwrap(),
            "copy-mode"
        );
        assert_eq!(
            engine.copy_mode_table_for_pane(second_pane).unwrap(),
            "copy-mode"
        );

        let targeted = engine
            .execute(
                &mut context,
                &command(
                    "set-window-option",
                    &["-t", &first_window.to_string(), "mode-keys", "vi"],
                ),
            )
            .expect("window mode table");
        assert_eq!(
            targeted.effects,
            [MuxEffect::ModeKeysChanged {
                window: Some(first_window)
            }]
        );
        assert_eq!(
            engine.copy_mode_table_for_pane(first_pane).unwrap(),
            "copy-mode-vi"
        );
        assert_eq!(
            engine.copy_mode_table_for_pane(second_pane).unwrap(),
            "copy-mode"
        );

        engine
            .execute(
                &mut context,
                &command(
                    "set-option",
                    &["-t", &first_window.to_string(), "mode-keys"],
                ),
            )
            .expect("toggle choice");
        assert_eq!(
            engine.copy_mode_table_for_pane(first_pane).unwrap(),
            "copy-mode"
        );

        let global = engine
            .execute(
                &mut context,
                &command("set-window-option", &["-g", "mode-keys", "vi"]),
            )
            .expect("global window default");
        assert_eq!(
            global.effects,
            [
                MuxEffect::ModeKeysChanged { window: None },
                MuxEffect::MuxOptionChanged {
                    option: MuxOptionKey::ModeKeys,
                    session: None,
                },
            ]
        );
        assert_eq!(
            engine.copy_mode_table_for_pane(first_pane).unwrap(),
            "copy-mode"
        );
        assert_eq!(
            engine.copy_mode_table_for_pane(second_pane).unwrap(),
            "copy-mode-vi"
        );

        engine
            .execute(
                &mut context,
                &command(
                    "set-option",
                    &["-u", "-t", &first_window.to_string(), "mode-keys"],
                ),
            )
            .expect("restore window inheritance");
        assert_eq!(
            engine.copy_mode_table_for_pane(first_pane).unwrap(),
            "copy-mode-vi"
        );

        engine
            .execute(
                &mut context,
                &command(
                    "set-option",
                    &["-o", "-t", &second_window.to_string(), "mode-keys", "emacs"],
                ),
            )
            .expect("set inherited option once");
        let quiet = engine
            .execute(
                &mut context,
                &command(
                    "set-option",
                    &["-oq", "-t", &second_window.to_string(), "mode-keys", "vi"],
                ),
            )
            .expect("quiet duplicate");
        assert!(quiet.effects.is_empty());
        assert_eq!(
            engine.copy_mode_table_for_pane(second_pane).unwrap(),
            "copy-mode"
        );

        for invalid in [
            command("set-window-option", &["-w", "mode-keys", "vi"]),
            command("set-option", &["mode-keys", "unknown"]),
        ] {
            assert!(engine.execute(&mut context, &invalid).is_err());
        }
        assert_eq!(
            engine.copy_mode_table_for_pane(second_pane).unwrap(),
            "copy-mode"
        );
    }

    #[test]
    fn synchronize_panes_commands_preserve_native_option_inheritance() {
        let mut engine = MuxEngine::default();
        let mut context = ExecutionContext::default();
        engine
            .execute(&mut context, &command("new-session", &[]))
            .unwrap();
        let first = context.pane.unwrap();
        engine
            .execute(&mut context, &command("split-window", &["-h"]))
            .unwrap();
        let second = context.pane.unwrap();

        let changed = engine
            .execute(
                &mut context,
                &command("set-option", &["-w", "synchronize-panes", "on"]),
            )
            .unwrap();
        assert!(changed.effects.contains(&MuxEffect::SnapshotChanged));
        assert_eq!(
            engine.synchronized_input_targets(first).unwrap(),
            [first, second]
        );

        engine
            .execute(
                &mut context,
                &command(
                    "set-option",
                    &["-p", "-t", &second.to_string(), "synchronize-panes", "off"],
                ),
            )
            .unwrap();
        assert_eq!(engine.synchronized_input_targets(first).unwrap(), [first]);
        assert_eq!(engine.synchronized_input_targets(second).unwrap(), [second]);

        engine
            .execute(
                &mut context,
                &command(
                    "set-option",
                    &["-p", "-u", "-t", &second.to_string(), "synchronize-panes"],
                ),
            )
            .unwrap();
        assert_eq!(
            engine.synchronized_input_targets(second).unwrap(),
            [first, second]
        );

        engine
            .execute(
                &mut context,
                &command("set-option", &["-w", "synchronize-panes"]),
            )
            .unwrap();
        assert_eq!(engine.synchronized_input_targets(first).unwrap(), [first]);

        engine
            .execute(
                &mut context,
                &command("setw", &["-g", "synchronize-panes", "on"]),
            )
            .unwrap();
        engine
            .execute(
                &mut context,
                &command(
                    "set-option",
                    &["-p", "-t", &second.to_string(), "synchronize-panes", "off"],
                ),
            )
            .unwrap();
        engine
            .execute(
                &mut context,
                &command("set-option", &["-U", "synchronize-panes"]),
            )
            .unwrap();
        assert_eq!(
            engine.synchronized_input_targets(first).unwrap(),
            [first, second]
        );
    }

    #[test]
    fn command_prompt_builds_a_native_client_effect() {
        let mut engine = MuxEngine::default();
        let mut context = ExecutionContext::default();
        let execution = engine
            .execute(
                &mut context,
                &command(
                    "command-prompt",
                    &[
                        "-b",
                        "-p",
                        "window name",
                        "-I",
                        "scratch",
                        "new-window -n %%",
                    ],
                ),
            )
            .unwrap();
        assert_eq!(
            execution.effects,
            vec![MuxEffect::CommandPrompt {
                prompt: "window name".to_owned(),
                input: "scratch".to_owned(),
                template: Some(CommandPromptTemplate::String("new-window -n %%".to_owned(),)),
                source: None,
                prompt_type: CommandPromptType::Command,
                mode: CommandPromptMode::Text,
                no_freeze: false,
            }]
        );

        engine
            .execute(&mut context, &command("new-session", &["-s", "work tree"]))
            .expect("prompt context session");
        engine
            .execute(&mut context, &command("rename-window", &["editor pane"]))
            .expect("prompt context window");
        let execution = engine
            .execute(
                &mut context,
                &command(
                    "command-prompt",
                    &["-I", "#S / #W", "rename-window -- '%%'"],
                ),
            )
            .expect("expanded prompt input");
        assert_eq!(
            execution.effects,
            vec![MuxEffect::CommandPrompt {
                prompt: ":".to_owned(),
                input: "work tree / editor pane".to_owned(),
                template: Some(CommandPromptTemplate::String(
                    "rename-window -- '%%'".to_owned(),
                )),
                source: None,
                prompt_type: CommandPromptType::Command,
                mode: CommandPromptMode::Text,
                no_freeze: false,
            }]
        );
        assert!(matches!(
            engine.execute(
                &mut context,
                &command("command-prompt", &["-F", "unsupported"]),
            ),
            Err(ServerError::UnsupportedCommand(message))
                if message == "command-prompt -F"
        ));

        for (index, value) in [
            (90, "a10e=display-message"),
            (
                91,
                "display-message=set-environment -g COMMAND_PROMPT_DOUBLE yes",
            ),
        ] {
            engine
                .execute(
                    &mut context,
                    &command(
                        "set-option",
                        &["-s", &format!("command-alias[{index}]"), value],
                    ),
                )
                .expect("set prompt alias");
        }
        let parsed = engine.parse_config("prompt.conf", "command-prompt -I x { a10e }");
        assert!(parsed.diagnostics.is_empty());
        let execution = engine
            .execute(&mut context, &parsed.commands[0])
            .expect("typed prompt effect");
        assert!(matches!(
            execution.effects.as_slice(),
            [MuxEffect::CommandPrompt {
                template: Some(CommandPromptTemplate::Commands(commands)),
                ..
            }] if commands.len() == 1 && commands[0].name == "display-message"
        ));
    }

    #[test]
    fn command_prompt_substitution_preserves_structured_arguments() {
        let engine = MuxEngine::default();
        let parsed = engine.parse_config(
            "prompt.conf",
            "if-shell -F 1 { set-environment -g PROMPT_VALUE '%%:%%' }",
        );
        assert!(parsed.diagnostics.is_empty());
        let mut commands = parsed.commands;
        engine
            .prepare_frozen_callback_invocations(&mut commands, "command-prompt")
            .expect("prepare typed prompt commands");
        let input = "x\" ; set-environment -g PROMPT_INJECTED yes ; display-message -p \"";
        engine
            .substitute_command_prompt_commands(&mut commands, input)
            .expect("substitute typed prompt input");

        let body = crate::parser::command_block_body(&commands[0].args[2])
            .expect("structured branch body");
        let nested = MuxEngine::parse_config_without_variable_expansion("prompt.conf", body);
        assert!(nested.diagnostics.is_empty());
        assert_eq!(nested.commands.len(), 1);
        assert_eq!(nested.commands[0].name, "set-environment");
        assert_eq!(
            nested.commands[0].args,
            ["-g", "PROMPT_VALUE", &format!("{input}:%%")]
        );
    }

    #[test]
    fn command_prompt_substitution_matches_tmux_placeholders_and_quoting() {
        assert_eq!(
            MuxEngine::substitute_command_prompt_template("%%:%%:%1:%1:%2", "abc"),
            "abc:%%:abc:abc:%2"
        );
        assert_eq!(
            MuxEngine::substitute_command_prompt_template("%%%|%1%", "\"\\$;~"),
            r#"\"\\\$\;\~|\"\\\$\;\~"#
        );

        let engine = MuxEngine::default();
        let parsed =
            engine.parse_config("prompt.conf", "display-message -p '%%:%%:%1:%1:%2:%%%:%1%'");
        assert!(parsed.diagnostics.is_empty());
        let mut commands = parsed.commands;
        engine
            .substitute_command_prompt_commands(&mut commands, "abc")
            .expect("substitute typed prompt placeholders");
        assert_eq!(commands[0].args[1], "abc:%%:abc:abc:%2:%%%:abc");
    }

    #[test]
    fn command_prompt_resolves_the_pinned_mode_ladder() {
        let mut engine = MuxEngine::default();
        let mut context = ExecutionContext::default();
        let mode = |engine: &mut MuxEngine, context: &mut ExecutionContext, flags: &[&str]| {
            let execution = engine
                .execute(context, &command("command-prompt", flags))
                .expect("prompt effect");
            match execution.effects.into_iter().next().expect("one effect") {
                MuxEffect::CommandPrompt {
                    mode,
                    prompt_type,
                    no_freeze,
                    ..
                } => (mode, prompt_type, no_freeze),
                other => panic!("unexpected effect {other:?}"),
            }
        };

        for (flags, expected) in [
            (
                &["-1", "-N", "-i", "-k", "-e"][..],
                CommandPromptMode::Single,
            ),
            (&["-N", "-i", "-k", "-e"], CommandPromptMode::Numeric),
            (&["-i", "-k", "-e"], CommandPromptMode::Incremental),
            (&["-k", "-e"], CommandPromptMode::Key),
            (&["-e"], CommandPromptMode::BackspaceExit),
            (&[], CommandPromptMode::Text),
        ] {
            let (resolved, prompt_type, no_freeze) = mode(&mut engine, &mut context, flags);
            assert_eq!(resolved, expected, "flags {flags:?}");
            assert_eq!(prompt_type, CommandPromptType::Command, "flags {flags:?}");
            assert!(!no_freeze, "flags {flags:?}");
        }

        assert_eq!(
            mode(&mut engine, &mut context, &["-1", "-C"]),
            (CommandPromptMode::Single, CommandPromptType::Command, true),
        );
        assert_eq!(
            mode(&mut engine, &mut context, &["-T", "search"]),
            (CommandPromptMode::Text, CommandPromptType::Search, false),
        );
        assert_eq!(
            mode(&mut engine, &mut context, &["-T", "command", "-k"]),
            (CommandPromptMode::Key, CommandPromptType::Command, false),
        );
        assert!(matches!(
            engine.execute(&mut context, &command("command-prompt", &["-T", "bogus"])),
            Err(ServerError::InvalidCommand(message)) if message == "unknown type: bogus"
        ));
        for parked in ["-F", "-l", "-P"] {
            assert!(matches!(
                engine.execute(&mut context, &command("command-prompt", &[parked])),
                Err(ServerError::UnsupportedCommand(message))
                    if message == format!("command-prompt {parked}")
            ));
        }
        assert!(matches!(
            engine.execute(&mut context, &command("command-prompt", &["-t", "%1"])),
            Err(ServerError::UnsupportedCommand(message)) if message == "command-prompt -t"
        ));
    }

    #[test]
    fn tree_chooser_preserves_session_window_and_pane_scopes() {
        let mut engine = MuxEngine::default();
        let mut context = ExecutionContext::default();
        engine
            .execute(&mut context, &command("new-session", &["-s", "work"]))
            .unwrap();
        let pane = context.pane.unwrap();

        assert_eq!(
            engine
                .execute(&mut context, &command("choose-tree", &["-Zs"]))
                .unwrap()
                .effects,
            vec![MuxEffect::ChooseTree {
                pane,
                kind: ChooseTreeKind::Windows,
                sessions_only: true,
                filter: None,
                format: None,
                hide_source: false,
                kill_source: false,
                sort: TmuxSort::parse(None, false, Some(TmuxSortOrder::Index)).unwrap(),
                key_format: None,
                template: None,
            }]
        );
        assert_eq!(
            engine
                .execute(
                    &mut context,
                    &command(
                        "choose-tree",
                        &["-Zw", "-f", "#{pane_active}", "-Oname", "-r"]
                    ),
                )
                .unwrap()
                .effects,
            vec![MuxEffect::ChooseTree {
                pane,
                kind: ChooseTreeKind::Windows,
                sessions_only: false,
                filter: Some("#{pane_active}".to_owned()),
                format: None,
                hide_source: false,
                kill_source: false,
                sort: TmuxSort::parse(Some("name"), true, Some(TmuxSortOrder::Index)).unwrap(),
                key_format: None,
                template: None,
            }]
        );
        assert_eq!(
            engine
                .execute(&mut context, &command("focus-sidebar", &[]))
                .unwrap()
                .effects,
            vec![MuxEffect::FocusSidebar { pane }]
        );

        assert_eq!(
            engine
                .execute(&mut context, &command("choose-tree", &[]))
                .unwrap()
                .effects,
            vec![MuxEffect::ChooseTree {
                pane,
                kind: ChooseTreeKind::Panes,
                sessions_only: false,
                filter: None,
                format: None,
                hide_source: false,
                kill_source: false,
                sort: TmuxSort::parse(None, false, Some(TmuxSortOrder::Index)).unwrap(),
                key_format: None,
                template: None,
            }]
        );

        assert_eq!(
            engine
                .execute(&mut context, &command("choose-tree", &["-sw"]))
                .unwrap()
                .effects,
            vec![MuxEffect::ChooseTree {
                pane,
                kind: ChooseTreeKind::Windows,
                sessions_only: true,
                filter: None,
                format: None,
                hide_source: false,
                kill_source: false,
                sort: TmuxSort::parse(None, false, Some(TmuxSortOrder::Index)).unwrap(),
                key_format: None,
                template: None,
            }]
        );
        let typed =
            CommandInvocation::new("choose-tree", ["{ display -p %% }"]).with_command_blocks([0]);
        let effects = engine.execute(&mut context, &typed).unwrap().effects;
        let [MuxEffect::ChooseTree { template, .. }] = effects.as_slice() else {
            panic!("typed tree chooser effect");
        };
        assert_eq!(template.as_deref(), Some("display-message -p \"%%\""));
        let typed_groups = CommandInvocation::new(
            "choose-tree",
            ["{ display -p one ; display -p two\ndisplay -p three }"],
        )
        .with_command_blocks([0]);
        let effects = engine.execute(&mut context, &typed_groups).unwrap().effects;
        let [MuxEffect::ChooseTree { template, .. }] = effects.as_slice() else {
            panic!("typed tree chooser group effect");
        };
        assert_eq!(
            template.as_deref(),
            Some("display-message -p one ; display-message -p two ;; display-message -p three")
        );
        assert!(matches!(
            engine
                .execute(
                    &mut context,
                    &command("choose-tree", &["select-pane -t %%"]),
                )
                .unwrap()
                .effects
                .as_slice(),
            [MuxEffect::ChooseTree {
                template: Some(template),
                ..
            }] if template == "select-pane -t %%"
        ));
        assert!(matches!(
            engine.execute(
                &mut context,
                &command(
                    "choose-tree",
                    &["-t", "missing", "-O", "not-an-order"],
                ),
            ),
            Err(ServerError::PaneNotFound(target)) if target == "missing"
        ));
    }

