    #[test]
    fn select_pane_input_flags_retarget_without_selecting() {
        let mut engine = MuxEngine::default();
        let mut context = ExecutionContext::default();
        engine
            .execute(&mut context, &command("new-session", &["-s", "work"]))
            .expect("session");
        let first = context.pane.expect("first pane");
        engine
            .execute(&mut context, &command("split-window", &["-d"]))
            .expect("split");
        let window = context.window.expect("window");
        let second = engine.state.windows[&window]
            .pane_order()
            .iter()
            .copied()
            .find(|pane| *pane != first)
            .expect("second pane");

        for (arguments, first_off, second_off) in [
            (vec!["-d", "-t", &second.to_string()[..]], "0", "1"),
            (vec!["-e", "-t", &second.to_string()[..]], "0", "0"),
            (vec!["-d", "-t", &first.to_string()[..]], "1", "0"),
            (vec!["-e", "-t", &first.to_string()[..]], "0", "0"),
        ] {
            engine
                .execute(&mut context, &command("select-pane", &arguments))
                .expect("input toggle");
            assert_eq!(
                format_of(
                    &mut engine,
                    &mut context,
                    &first.to_string(),
                    "#{pane_input_off}"
                ),
                first_off
            );
            assert_eq!(
                format_of(
                    &mut engine,
                    &mut context,
                    &second.to_string(),
                    "#{pane_input_off}"
                ),
                second_off
            );
            assert_eq!(engine.state.windows[&window].active_pane, first);
        }

        engine
            .execute(
                &mut context,
                &command("select-pane", &["-d", "-t", &second.to_string()]),
            )
            .expect("disable input");
        engine
            .execute(
                &mut context,
                &command("select-pane", &["-d", "-e", "-t", &second.to_string()]),
            )
            .expect("enable wins over disable");
        assert_eq!(
            format_of(
                &mut engine,
                &mut context,
                &second.to_string(),
                "#{pane_input_off}"
            ),
            "0"
        );

        engine
            .execute(
                &mut context,
                &command("select-pane", &["-D", "-d", "-t", &first.to_string()]),
            )
            .expect("direction resolves before the input flag");
        assert_eq!(
            format_of(
                &mut engine,
                &mut context,
                &second.to_string(),
                "#{pane_input_off}"
            ),
            "1"
        );
        assert_eq!(engine.state.windows[&window].active_pane, first);

        engine
            .execute(
                &mut context,
                &command("select-pane", &["-t", &second.to_string()]),
            )
            .expect("visit second");
        engine
            .execute(
                &mut context,
                &command("select-pane", &["-t", &first.to_string()]),
            )
            .expect("back to first");
        engine
            .execute(&mut context, &command("select-pane", &["-l", "-e"]))
            .expect("enable input on the last pane");
        assert_eq!(
            format_of(
                &mut engine,
                &mut context,
                &second.to_string(),
                "#{pane_input_off}"
            ),
            "0"
        );
        engine
            .execute(&mut context, &command("select-pane", &["-l", "-d"]))
            .expect("disable input on the last pane");
        assert_eq!(
            format_of(
                &mut engine,
                &mut context,
                &second.to_string(),
                "#{pane_input_off}"
            ),
            "1"
        );
        assert_eq!(engine.state.windows[&window].active_pane, first);
    }

    #[test]
    fn select_pane_style_flag_writes_both_pane_styles_and_then_selects() {
        let mut engine = MuxEngine::default();
        let mut context = ExecutionContext::default();
        engine
            .execute(&mut context, &command("new-session", &["-s", "work"]))
            .expect("session");
        let first = context.pane.expect("first pane");
        engine
            .execute(&mut context, &command("split-window", &["-d"]))
            .expect("split");
        let window = context.window.expect("window");
        let second = engine.state.windows[&window]
            .pane_order()
            .iter()
            .copied()
            .find(|pane| *pane != first)
            .expect("second pane");

        let styled = engine
            .execute(
                &mut context,
                &command("select-pane", &["-P", "bg=red", "-t", &second.to_string()]),
            )
            .expect("pane style");
        assert_eq!(
            styled.effects,
            vec![
                MuxEffect::TerminalKnobsChanged {
                    window: None,
                    pane: Some(second),
                },
                MuxEffect::SnapshotChanged,
            ]
        );
        assert_eq!(engine.state.windows[&window].active_pane, second);
        for name in ["window-style", "window-active-style"] {
            assert_eq!(
                engine
                    .execute(
                        &mut context,
                        &command("show-options", &["-pv", "-t", &second.to_string(), name]),
                    )
                    .expect("style readback")
                    .output,
                "bg=red"
            );
        }

        engine
            .execute(
                &mut context,
                &command("select-pane", &["-t", &first.to_string()]),
            )
            .expect("back to first");
        assert_eq!(
            engine
                .execute(
                    &mut context,
                    &command("select-pane", &["-g", "-t", &second.to_string()]),
                )
                .expect("print pane style")
                .output,
            "bg=red"
        );
        assert_eq!(engine.state.windows[&window].active_pane, first);
        assert_eq!(
            engine
                .execute(
                    &mut context,
                    &command("select-pane", &["-g", "-t", &first.to_string()]),
                )
                .expect("print default pane style")
                .output,
            "default"
        );

        engine
            .execute(
                &mut context,
                &command(
                    "set-option",
                    &["-w", "-t", "work:0", "window-style", "bg=green"],
                ),
            )
            .expect("window style");
        assert_eq!(
            engine
                .execute(
                    &mut context,
                    &command("select-pane", &["-g", "-t", &first.to_string()]),
                )
                .expect("print inherited pane style")
                .output,
            "bg=green"
        );

        assert!(matches!(
            engine.execute(
                &mut context,
                &command(
                    "set-option",
                    &["-p", "-t", &first.to_string(), "window-style", "bogus=zzz"],
                ),
            ),
            Err(ServerError::InvalidCommand(message)) if message == "invalid style: bogus=zzz"
        ));
        engine
            .execute(
                &mut context,
                &command(
                    "select-pane",
                    &["-P", "bogus=zzz", "-t", &first.to_string()],
                ),
            )
            .expect("the pin's -P never validates the style");
        assert_eq!(
            engine
                .execute(
                    &mut context,
                    &command("select-pane", &["-g", "-t", &first.to_string()]),
                )
                .expect("print unvalidated pane style")
                .output,
            "bogus=zzz"
        );

        engine
            .execute(
                &mut context,
                &command("select-pane", &["-t", &second.to_string()]),
            )
            .expect("select second");
        assert_eq!(
            engine
                .execute(
                    &mut context,
                    &command(
                        "select-pane",
                        &["-P", "bg=blue", "-g", "-t", &first.to_string()],
                    ),
                )
                .expect("style then print")
                .output,
            "bg=blue"
        );
        assert_eq!(engine.state.windows[&window].active_pane, second);

        engine
            .execute(
                &mut context,
                &command(
                    "select-pane",
                    &["-m", "-P", "bg=yellow", "-t", &second.to_string()],
                ),
            )
            .expect("mark wins over style");
        assert_eq!(engine.state.marked_pane(), Some(second));
        assert_eq!(
            engine
                .execute(
                    &mut context,
                    &command("select-pane", &["-g", "-t", &second.to_string()]),
                )
                .expect("style untouched by the mark path")
                .output,
            "bg=red"
        );
    }

    #[test]
    fn marked_target_alias_is_a_whole_target_and_names_its_own_miss() {
        let mut engine = MuxEngine::default();
        let mut context = ExecutionContext::default();
        engine
            .execute(&mut context, &command("new-session", &["-s", "work"]))
            .expect("session");
        let first = context.pane.expect("first pane");
        engine
            .execute(&mut context, &command("split-window", &["-d"]))
            .expect("split");
        let window = context.window.expect("window");
        let second = engine.state.windows[&window]
            .pane_order()
            .iter()
            .copied()
            .find(|pane| *pane != first)
            .expect("second pane");

        for target in ["{marked}", "~"] {
            assert!(matches!(
                engine.execute(&mut context, &command("kill-pane", &["-t", target])),
                Err(ServerError::InvalidCommand(message)) if message == "no marked target"
            ));
            assert!(matches!(
                engine.execute(&mut context, &command("select-window", &["-t", target])),
                Err(ServerError::InvalidCommand(message)) if message == "no marked target"
            ));
            assert_eq!(
                engine
                    .execute(
                        &mut context,
                        &command(
                            "display-message",
                            &[
                                "-p",
                                "-t",
                                target,
                                "#{session_name}:#{window_index}.#{pane_index}"
                            ],
                        ),
                    )
                    .expect("marked miss falls through display-message")
                    .output,
                ":."
            );
        }

        engine
            .execute(
                &mut context,
                &command("select-pane", &["-m", "-t", &second.to_string()]),
            )
            .expect("mark second");
        for target in ["{marked}", "~"] {
            assert_eq!(
                engine.resolve_pane(Some(target), context.window, context.pane),
                Ok(second),
                "pane slot for {target}"
            );
            assert_eq!(
                engine.resolve_window(Some(target), context.session, context.window),
                Ok(window),
                "window slot for {target}"
            );
            assert_eq!(
                engine
                    .state
                    .resolve_session(Some(target), context.session)
                    .expect("session slot"),
                engine.state.windows[&window].session
            );
        }
        assert_eq!(
            engine
                .execute(
                    &mut context,
                    &command(
                        "display-message",
                        &[
                            "-p",
                            "-t",
                            "{marked}.0",
                            "#{session_name}:#{window_index}.#{pane_index}"
                        ],
                    ),
                )
                .expect("a split component is an ordinary name")
                .output,
            ":."
        );
    }

    #[test]
    fn pane_targets_read_the_pins_direction_and_compass_aliases() {
        let mut engine = MuxEngine::default();
        let mut context = ExecutionContext::default();
        engine
            .execute(&mut context, &command("new-session", &["-s", "work"]))
            .expect("session");
        engine
            .execute(&mut context, &command("split-window", &["-d", "-h"]))
            .expect("horizontal split");
        let window = context.window.expect("window");
        let first = context.pane.expect("first pane").to_string();
        engine
            .execute(
                &mut context,
                &command("split-window", &["-d", "-v", "-t", &first]),
            )
            .expect("vertical split");
        let order = engine.state.windows[&window].pane_order().to_vec();
        let (top_left, bottom_left, right) = (order[0], order[1], order[2]);
        assert_eq!(engine.state.windows[&window].active_pane, top_left);

        for (target, expected) in [
            ("top", top_left),
            ("bottom", bottom_left),
            ("left", top_left),
            ("right", right),
            ("top-left", top_left),
            ("top-right", right),
            ("bottom-left", bottom_left),
            ("bottom-right", right),
            ("TOP-RIGHT", right),
            ("{top}", top_left),
            ("{bottom}", bottom_left),
            ("{left}", top_left),
            ("{right}", right),
            ("{top-left}", top_left),
            ("{top-right}", right),
            ("{bottom-left}", bottom_left),
            ("{bottom-right}", right),
            ("{up-of}", bottom_left),
            ("{down-of}", bottom_left),
            ("{left-of}", right),
            ("{right-of}", right),
        ] {
            assert_eq!(
                engine.resolve_pane(Some(target), context.window, context.pane),
                Ok(expected),
                "target {target}"
            );
        }

        engine
            .execute(
                &mut context,
                &command("resize-pane", &["-Z", "-t", &top_left.to_string()]),
            )
            .expect("zoom");
        for target in ["bottom", "bottom-right", "{right}"] {
            assert_eq!(
                engine.resolve_pane(Some(target), context.window, context.pane),
                Ok(top_left),
                "zoomed target {target}"
            );
        }
    }

    #[test]
    fn exact_match_prefix_is_scoped_to_the_session_and_window_slots() {
        let mut engine = MuxEngine::default();
        let mut context = ExecutionContext::default();
        engine
            .execute(&mut context, &command("new-session", &["-s", "alpha"]))
            .expect("session");
        engine
            .execute(
                &mut context,
                &command("rename-window", &["-t", "alpha:0", "win0"]),
            )
            .expect("rename");

        for (arguments, message) in [
            (
                vec!["-t", "=alpha", "history-limit", "1234"],
                "no such session: =alpha",
            ),
            (
                vec!["-t", "=alp", "history-limit", "1234"],
                "no such session: =alp",
            ),
            (
                vec!["-t", "nope", "history-limit", "1234"],
                "no such session: nope",
            ),
            (
                vec!["-w", "-t", "=win0", "aggressive-resize", "on"],
                "no such window: =win0",
            ),
            (
                vec!["-p", "-t", "=alpha", "remain-on-exit", "on"],
                "no such pane: =alpha",
            ),
        ] {
            assert!(
                matches!(
                    engine.execute(&mut context, &command("set-option", &arguments)),
                    Err(ServerError::InvalidCommand(actual)) if actual == message
                ),
                "set-option {arguments:?}"
            );
        }

        assert!(matches!(
            engine.execute(&mut context, &command("kill-pane", &["-t", "=alpha"])),
            Err(ServerError::PaneNotFound(target)) if target == "=alpha"
        ));
        assert!(matches!(
            engine.execute(&mut context, &command("select-pane", &["-t", "=win0"])),
            Err(ServerError::PaneNotFound(target)) if target == "=win0"
        ));
        assert!(matches!(
            engine.execute(&mut context, &command("has-session", &["-t", "=alp"])),
            Err(ServerError::SessionNotFound(target)) if target == "alp"
        ));
        assert!(matches!(
            engine.execute(&mut context, &command("kill-window", &["-t", "=wi"])),
            Err(ServerError::WindowNotFound(target)) if target == "wi"
        ));

        engine
            .execute(
                &mut context,
                &command("set-option", &["-t", "=alpha:", "history-limit", "1234"]),
            )
            .expect("a colon moves the token into the session slot");
        assert_eq!(
            engine.history_limit_for_session(context.session.expect("session")),
            1234
        );
        engine
            .execute(
                &mut context,
                &command(
                    "set-window-option",
                    &["-t", "=win0", "aggressive-resize", "on"],
                ),
            )
            .expect("set-window-option resolves a window target");
        assert_eq!(
            engine
                .execute(
                    &mut context,
                    &command(
                        "show-window-options",
                        &["-v", "-t", "alpha:0", "aggressive-resize"]
                    ),
                )
                .expect("aggressive-resize readback")
                .output,
            "on"
        );
        engine
            .execute(&mut context, &command("has-session", &["-t", "=alpha"]))
            .expect("has-session resolves a session target");
    }

    #[test]
    fn split_window_retain_flags_write_the_pins_pane_local_key_retention() {
        let mut engine = MuxEngine::default();
        let mut context = ExecutionContext::default();
        engine
            .execute(&mut context, &command("new-session", &["-s", "work"]))
            .expect("session");
        let first = context.pane.expect("first pane");
        let window = context.window.expect("window");

        for (arguments, format) in [
            (vec!["-d", "-k", "-t", "%0"], None),
            (
                vec!["-d", "-m", "gone #{pane_dead_status}", "-t", "%0"],
                Some("gone #{pane_dead_status}"),
            ),
            (vec!["-d", "-k", "-m", "both", "-t", "%0"], Some("both")),
        ] {
            let arguments = arguments
                .into_iter()
                .map(|argument| {
                    if argument == "%0" {
                        first.to_string()
                    } else {
                        argument.to_owned()
                    }
                })
                .collect::<Vec<_>>();
            let arguments = arguments.iter().map(String::as_str).collect::<Vec<_>>();
            let execution = engine
                .execute(&mut context, &command("split-window", &arguments))
                .expect("retained split");
            let Some(MuxEffect::PaneCreated { pane, .. }) = execution.effects.first() else {
                panic!("missing pane creation effect");
            };
            let pane = *pane;
            assert_eq!(
                engine
                    .execute(
                        &mut context,
                        &command(
                            "show-options",
                            &["-pv", "-t", &pane.to_string(), "remain-on-exit"]
                        ),
                    )
                    .expect("remain-on-exit readback")
                    .output,
                "key"
            );
            assert_eq!(
                engine
                    .execute(
                        &mut context,
                        &command(
                            "show-options",
                            &["-pv", "-t", &pane.to_string(), "remain-on-exit-format"],
                        ),
                    )
                    .expect("remain-on-exit-format readback")
                    .output,
                format.unwrap_or_default()
            );
            assert!(engine.retain_exited_pane(pane, false).expect("clean exit"));
            assert!(engine.retain_exited_pane(pane, true).expect("failed exit"));
            engine
                .state
                .mark_pane_dead(pane, Some(0))
                .expect("retained pane dies");
            assert!(engine.dead_pane_dismisses_on_key(pane));
            assert!(!engine.dead_pane_dismisses_on_key(first));
            engine
                .execute(
                    &mut context,
                    &command("kill-pane", &["-t", &pane.to_string()]),
                )
                .expect("kill the retained pane");
        }

        assert_eq!(
            engine
                .execute(
                    &mut context,
                    &command(
                        "show-window-options",
                        &["-v", "-t", "work:0", "remain-on-exit"]
                    ),
                )
                .expect("window scope readback")
                .output,
            ""
        );
        assert_eq!(engine.state.windows[&window].panes.len(), 1);

        for arguments in [vec!["-d", "-m"], vec!["-d", "-k", "-m"]] {
            assert!(matches!(
                engine.execute(&mut context, &command("split-window", &arguments)),
                Err(ServerError::CommandParse(message))
                    if message == "command split-window: -m expects an argument"
            ));
        }
    }

    #[test]
    fn break_pane_floating_placement_flags_stay_loudly_unsupported() {
        let mut engine = MuxEngine::default();
        let mut context = ExecutionContext::default();
        engine
            .execute(&mut context, &command("new-session", &["-s", "work"]))
            .expect("session");
        engine
            .execute(&mut context, &command("split-window", &["-d"]))
            .expect("split");
        let window = context.window.expect("window");
        let source = engine.state.windows[&window].pane_order()[1].to_string();

        for (flag, value) in [
            ("-W", None),
            ("-x", Some("20")),
            ("-y", Some("6")),
            ("-X", Some("10")),
            ("-Y", Some("3")),
        ] {
            let mut arguments = vec![flag];
            arguments.extend(value);
            arguments.extend(["-s", source.as_str()]);
            assert!(
                matches!(
                    engine.execute(&mut context, &command("break-pane", &arguments)),
                    Err(ServerError::UnsupportedCommand(message))
                        if message == format!("break-pane {flag}")
                ),
                "break-pane {flag}"
            );
        }
        assert_eq!(engine.state.windows[&window].panes.len(), 2);
        assert_eq!(engine.state.windows.len(), 1);
        assert_eq!(
            engine
                .execute(
                    &mut context,
                    &command(
                        "display-message",
                        &["-p", "-t", &source, "#{pane_floating_flag}"]
                    ),
                )
                .expect("floating flag readback")
                .output,
            "0"
        );
    }

    #[test]
    fn split_window_zoom_follows_the_post_spawn_active_pane() {
        let mut engine = MuxEngine::default();
        let mut context = ExecutionContext::default();
        engine
            .execute(&mut context, &command("new-session", &["-s", "work"]))
            .unwrap();
        let first = context.pane.unwrap();
        let window = context.window.unwrap();
        engine
            .execute(&mut context, &command("split-window", &["-d", "-h"]))
            .unwrap();

        engine
            .execute(
                &mut context,
                &command("resize-pane", &["-Z", "-t", &first.to_string()]),
            )
            .unwrap();
        assert_eq!(engine.state.windows[&window].zoomed_pane, Some(first));
        engine
            .execute(
                &mut context,
                &command("split-window", &["-d", "-h", "-t", &first.to_string()]),
            )
            .unwrap();
        assert_eq!(engine.state.windows[&window].active_pane, first);
        assert_eq!(engine.state.windows[&window].zoomed_pane, None);

        engine
            .execute(
                &mut context,
                &command(
                    "split-window",
                    &["-d", "-h", "-Z", "-t", &first.to_string()],
                ),
            )
            .unwrap();
        assert_eq!(engine.state.windows[&window].active_pane, first);
        assert_eq!(engine.state.windows[&window].zoomed_pane, Some(first));
        engine
            .execute(
                &mut context,
                &command("resize-pane", &["-Z", "-t", &first.to_string()]),
            )
            .unwrap();

        engine
            .execute(
                &mut context,
                &command("split-window", &["-h", "-Z", "-t", &first.to_string()]),
            )
            .unwrap();
        let created = context.pane.unwrap();
        assert_ne!(created, first);
        assert_eq!(engine.state.windows[&window].active_pane, created);
        assert_eq!(engine.state.windows[&window].zoomed_pane, Some(created));
    }

    #[test]
    fn native_splits_reveal_by_default_and_preserve_zoom_when_detached() {
        for (name, reveal_args, detached_args) in [
            ("split-picker", &["-h"][..], &["-d", "-h"][..]),
            (
                "split-browser",
                &["-h", "https://example.com"][..],
                &["-d", "-h", "https://detached.example"][..],
            ),
        ] {
            let mut engine = MuxEngine::default();
            let mut context = ExecutionContext::default();
            engine
                .execute(&mut context, &command("new-session", &["-s", "work"]))
                .unwrap();
            let first = context.pane.unwrap();
            let window = context.window.unwrap();
            engine
                .execute(&mut context, &command("split-window", &["-d", "-h"]))
                .unwrap();
            engine
                .execute(
                    &mut context,
                    &command("resize-pane", &["-Z", "-t", &first.to_string()]),
                )
                .unwrap();

            engine
                .execute(&mut context, &command(name, reveal_args))
                .unwrap();
            let revealed = context.pane.unwrap();
            assert_ne!(revealed, first);
            assert_eq!(engine.state.windows[&window].active_pane, revealed);
            assert_eq!(engine.state.windows[&window].zoomed_pane, None);

            engine
                .execute(
                    &mut context,
                    &command("resize-pane", &["-Z", "-t", &revealed.to_string()]),
                )
                .unwrap();
            let detached = engine
                .execute(&mut context, &command(name, detached_args))
                .unwrap();
            let hidden = match detached.effects.first() {
                Some(MuxEffect::PaneCreated { pane, .. }) => *pane,
                effects => panic!("expected pane creation, got {effects:?}"),
            };
            assert_ne!(hidden, revealed);
            assert_eq!(context.pane, Some(revealed));
            assert_eq!(engine.state.windows[&window].active_pane, revealed);
            assert_eq!(engine.state.windows[&window].zoomed_pane, Some(revealed));
        }
    }

    #[test]
    fn select_pane_changes_pane_activity_without_touching_window_or_session_selection() {
        let mut engine = MuxEngine::default();
        let mut context = ExecutionContext::default();
        engine
            .execute(&mut context, &command("new-session", &["-s", "work"]))
            .unwrap();
        let session = context.session.unwrap();
        let first_window = context.window.unwrap();
        let first = context.pane.unwrap();
        engine
            .execute(&mut context, &command("split-window", &["-h"]))
            .unwrap();
        let second = context.pane.unwrap();
        let window_activity = engine.state.windows[&first_window].activity;
        let first_active_point = engine.state.windows[&first_window].panes[&first].active_point;

        engine
            .execute(
                &mut context,
                &command("select-pane", &["-t", &first.to_string()]),
            )
            .unwrap();
        assert_eq!(engine.state.sessions[&session].active_window, first_window);
        assert_eq!(engine.state.windows[&first_window].active_pane, first);
        assert_eq!(context.pane, Some(first));
        assert_eq!(
            engine.state.windows[&first_window].activity,
            window_activity
        );
        assert!(
            engine.state.windows[&first_window].panes[&first].active_point > first_active_point
        );

        engine
            .execute(&mut context, &command("new-window", &["-n", "other"]))
            .unwrap();
        let other_window = context.window.unwrap();
        let other_pane = context.pane.unwrap();
        let first_window_activity = engine.state.windows[&first_window].activity;
        engine
            .execute(
                &mut context,
                &command("select-pane", &["-t", &second.to_string()]),
            )
            .unwrap();
        assert_eq!(engine.state.sessions[&session].active_window, other_window);
        assert_eq!(engine.state.windows[&first_window].active_pane, second);
        assert_eq!(context.window, Some(first_window));
        assert_eq!(context.pane, Some(second));
        assert_eq!(
            engine.state.windows[&first_window].activity,
            first_window_activity
        );

        context = ExecutionContext::for_pane(&engine.state, other_pane).unwrap();
        let generation = engine.state.generation();
        let no_op = engine
            .execute(
                &mut context,
                &command("select-pane", &["-t", &second.to_string()]),
            )
            .unwrap();
        assert_eq!(engine.state.sessions[&session].active_window, other_window);
        assert_eq!(context.window, Some(other_window));
        assert_eq!(context.pane, Some(other_pane));
        assert_eq!(engine.state.generation(), generation);
        assert!(no_op.effects.is_empty());
    }

